
import os
import sys
import glob
import tkinter as tk
from tkinter import messagebox

def get_readable_size(path):
    # Ensure we use an absolute path for globbing
    search_path = os.path.join(path, '**', '*')
    
    # Calculate total size of files safely
    total_bytes = 0
    for f in glob.iglob(search_path, recursive=True):
        try:
            if os.path.isfile(f):
                total_bytes += os.path.getsize(f)
        except (PermissionError, FileNotFoundError):
            continue  # Skip locked system files or broken symlinks

    # Format the bytes into a human-readable string
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if total_bytes < 1024:
            return f"{total_bytes:.2f} {unit}"
        total_bytes /= 1024
    return f"{total_bytes:.2f} PB"

if __name__ == "__main__":
    print(f"Please wait! Calculating size of {os.path.abspath(sys.argv[1])}")
    # Get the folder path passed by the Windows context menu
    if len(sys.argv) > 1:
        target_dir = sys.argv[1]
        
        # Hide the main root window of tkinter
        root = tk.Tk()
        root.withdraw()
        
        # Calculate and display the result
        folder_name = os.path.basename(os.path.normpath(target_dir))
        size_str = get_readable_size(target_dir)
        
        messagebox.showinfo("Folder Size Calculator", f"Folder: {folder_name}\nTotal Size: {size_str}")
